import { useState, useEffect, useRef, useMemo } from 'react';
import QRCode from 'qrcode';
import { AvulsoProductItem } from '@/lib/types';
import { getPublicApiUrl } from '@/lib/contentStore';
import { isLocalhost } from '@/lib/env';
import { useScrollLock } from '@/hooks/useScrollLock';
import { UniversalCheckoutContext, CheckoutDetailItem } from './types';

interface UseCheckoutOrderOptions {
  isOpen: boolean;
  onClose: () => void;
  product?: AvulsoProductItem | null;
  checkoutContext?: UniversalCheckoutContext | null;
  onSuccess?: (result: { orderId: string; purchaseToken?: string }) => void;
}

export function useCheckoutOrder({
  isOpen,
  onClose,
  product,
  checkoutContext,
  onSuccess,
}: UseCheckoutOrderOptions) {
  const [copied, setCopied] = useState(false);
  const [pixPayload, setPixPayload] = useState<string>('');
  const [qrCodeUrl, setQrCodeUrl] = useState<string>('');
  const [timeLeft, setTimeLeft] = useState(15 * 60);
  const [paymentStatus, setPaymentStatus] = useState<
    'pending' | 'verifying' | 'approved' | 'rejected' | 'expired'
  >('pending');
  const [orderId, setOrderId] = useState<string | null>(null);
  const [purchaseToken, setPurchaseToken] = useState<string | null>(null);
  const [displayAmount, setDisplayAmount] = useState<number>(29.9);
  const [isGeneratingPix, setIsGeneratingPix] = useState(false);
  const [generationError, setGenerationError] = useState<string | null>(null);
  const [retryCount, setRetryCount] = useState(0);
  const [isSimulating, setIsSimulating] = useState(false);
  const [paymentMethodTab, setPaymentMethodTab] = useState<'pix' | 'card'>('pix');
  const [isRedirectingToCard, setIsRedirectingToCard] = useState(false);
  const [cardError, setCardError] = useState<string | null>(null);
  const [buyerEmail, setBuyerEmail] = useState('');
  const [emailSubmitted, setEmailSubmitted] = useState(false);
  const [isSavingEmail, setIsSavingEmail] = useState(false);
  const [emailError, setEmailError] = useState<string | null>(null);
  const [recoveryEmailInput, setRecoveryEmailInput] = useState('');
  const [isRecoveringEmail, setIsRecoveringEmail] = useState(false);
  const [recoveryMsg, setRecoveryMsg] = useState<string | null>(null);

  const isLocal = isLocalhost();
  const pixCreatedForRef = useRef<string | null>(null);

  const activeContext: UniversalCheckoutContext | null = useMemo(() => {
    if (checkoutContext) return checkoutContext;
    if (product) {
      const clean = (product.price || '').replace(/[^\d,.]/g, '').replace(',', '.');
      const num = parseFloat(clean);
      const parsedPrice = isNaN(num) || num <= 0 ? 29.9 : num;
      const productSlug = product.slug || product.id?.replace(/^avulso-/, '') || '';

      const details: CheckoutDetailItem[] = [];
      if (product.duration) {
        details.push({ label: 'Duração', value: product.duration });
      }
      const rawCount = (product as any).photoCount || product.technicalDetails?.mediaCount || (product.exclusivePhotos?.length ? `${product.exclusivePhotos.length} fotos` : null);
      if (rawCount) {
        details.push({ label: 'Arquivos', value: String(rawCount) });
      }

      return {
        type: 'avulso',
        id: productSlug,
        title: product.title,
        subtitle: 'Acesso vitalício sem renovação',
        priceFormatted: product.price || `R$ ${parsedPrice.toFixed(2).replace('.', ',')}`,
        numericPrice: parsedPrice,
        badge: product.badge,
        imageUrl: product.imageUrl,
        details,
        accessUrl: `/assistir/${productSlug}`,
        accessButtonText: 'Assistir / Visualizar Obra Agora',
      };
    }
    return null;
  }, [checkoutContext, product]);

  useScrollLock(isOpen && !!activeContext);

  useEffect(() => {
    if (!isOpen) return;
    const handleKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, [isOpen, onClose]);

  useEffect(() => {
    if (pixPayload && !qrCodeUrl) {
      QRCode.toDataURL(pixPayload, {
        width: 320,
        margin: 1,
        color: { dark: '#09090b', light: '#ffffff' },
        errorCorrectionLevel: 'M',
      })
        .then((url) => setQrCodeUrl(url))
        .catch(() => {});
    }
  }, [pixPayload, qrCodeUrl]);

  useEffect(() => {
    if (!isOpen || paymentStatus !== 'pending') return;
    const interval = setInterval(() => {
      setTimeLeft((prev) => {
        if (prev <= 1) {
          setPaymentStatus('expired');
          clearInterval(interval);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);
    return () => clearInterval(interval);
  }, [isOpen, paymentStatus]);

  const saveAccessLocally = (token: string) => {
    if (!activeContext) return;
    try {
      if (activeContext.type === 'avulso') {
        localStorage.setItem(`nua_access_token_${activeContext.id}`, token);
        localStorage.setItem(`nua_unlocked_${activeContext.id}`, 'true');
      } else if (activeContext.type === 'chamada') {
        localStorage.setItem('nua_saved_booking_token', token);
      } else if (activeContext.type === 'personalizado') {
        localStorage.setItem('nua_saved_personalizado_token', token);
      }
    } catch {}
  };

  const handleCopyPix = () => {
    if (!pixPayload) return;
    navigator.clipboard?.writeText(pixPayload);
    setCopied(true);
    setTimeout(() => setCopied(false), 2500);
  };

  const handleSaveBuyerEmail = async () => {
    const cleanEmail = (buyerEmail || '').trim().toLowerCase();
    if (!cleanEmail || !cleanEmail.includes('@') || !cleanEmail.includes('.')) {
      setEmailError('Informe um e-mail válido.');
      return;
    }
    if (!orderId) {
      setEmailError('ID do pedido não encontrado.');
      return;
    }

    setIsSavingEmail(true);
    setEmailError(null);
    try {
      const apiUrl = getPublicApiUrl();
      const res = await fetch(`${apiUrl}/api/payments/update-email`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ orderId, email: cleanEmail }),
      });
      const data = await res.json().catch(() => ({}));
      if (data.success) {
        setEmailSubmitted(true);
        saveAccessLocally(purchaseToken || orderId);
      } else {
        throw new Error(data.error || 'Erro ao salvar e-mail.');
      }
    } catch (err: any) {
      setEmailError(err?.message || 'Erro ao salvar e-mail. Tente novamente.');
    } finally {
      setIsSavingEmail(false);
    }
  };

  const handleQuickRecoverEmail = async () => {
    const cleanEmail = (recoveryEmailInput || '').trim().toLowerCase();
    if (!cleanEmail || !cleanEmail.includes('@') || !cleanEmail.includes('.')) {
      setRecoveryMsg('Informe um e-mail válido.');
      return;
    }

    setIsRecoveringEmail(true);
    setRecoveryMsg(null);
    try {
      const apiUrl = getPublicApiUrl();
      const res = await fetch(`${apiUrl}/api/payments/send-otp`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ search: cleanEmail }),
      });
      const data = await res.json().catch(() => ({}));
      if (data.success) {
        setRecoveryMsg('✓ Pedido localizado no banco de dados! E-mail reenviado com sucesso.');
        if (data.orderId) {
          setOrderId(data.orderId);
        }
        setTimeout(() => {
          setPaymentStatus('approved');
        }, 1500);
      } else {
        throw new Error(data.error || 'Nenhum pedido pago localizado com este e-mail.');
      }
    } catch (err: any) {
      setRecoveryMsg(err?.message || 'Erro ao localizar pedido ou enviar e-mail.');
    } finally {
      setIsRecoveringEmail(false);
    }
  };

  const handleSimulateApprove = async () => {
    if (!isLocal || !orderId || isSimulating) return;
    setIsSimulating(true);
    try {
      const apiUrl = getPublicApiUrl();
      const endpoint = `${apiUrl}/api/payments/simulate-approve`;
      const res = await fetch(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ orderId }),
      });
      const data = await res.json().catch(() => ({}));
      if (data.success && (data.paid || data.status === 'approved')) {
        setPaymentStatus('approved');
        const tokenToSave = data.purchaseToken || purchaseToken || orderId;
        saveAccessLocally(tokenToSave);
        onSuccess?.({ orderId, purchaseToken: tokenToSave });
      } else {
        throw new Error(data.error || 'Falha ao simular aprovação.');
      }
    } catch (err: any) {
      console.error('[Simulate Approve Error]:', err);
      alert(err?.message || 'Erro ao simular aprovação.');
    } finally {
      setIsSimulating(false);
    }
  };

  const handleStartCardCheckout = async () => {
    if (!activeContext || isRedirectingToCard) return;
    setIsRedirectingToCard(true);
    setCardError(null);
    try {
      const apiUrl = getPublicApiUrl();
      const endpoint = `${apiUrl}/api/stripe/create-checkout`;
      const genOrderId = orderId || `ord_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 6)}`;

      let successUrl = `${window.location.origin}/assistir/${activeContext.id}?token=${genOrderId}&paid=stripe`;
      if (activeContext.type === 'chamada') {
        successUrl = `${window.location.origin}/chamadas?token=${genOrderId}&paid=stripe`;
      } else if (activeContext.type === 'personalizado') {
        successUrl = `${window.location.origin}/personalizados/pedido?token=${genOrderId}&paid=stripe`;
      }

      const res = await fetch(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          orderId: genOrderId,
          orderType: activeContext.type,
          customerEmail: buyerEmail || undefined,
          customerName: 'Cliente Nua Borges',
          items: [
            {
              id: activeContext.id,
              name: activeContext.title,
              amount: displayAmount || activeContext.numericPrice,
              quantity: 1,
            },
          ],
          successUrl,
          cancelUrl: window.location.href,
        }),
      });

      const data = await res.json().catch(() => ({}));
      if (data.success && data.checkoutUrl) {
        window.location.href = data.checkoutUrl;
      } else {
        throw new Error(data.error || 'Falha ao iniciar checkout no Stripe.');
      }
    } catch (err: any) {
      console.error('[Card Checkout Error]:', err);
      setCardError(err?.message || 'Não foi possível redirecionar para o pagamento com cartão.');
      setIsRedirectingToCard(false);
    }
  };

  // Inicialização do pagamento Pix
  useEffect(() => {
    if (!isOpen || !activeContext) {
      pixCreatedForRef.current = null;
      setPaymentStatus('pending');
      setTimeLeft(15 * 60);
      setOrderId(null);
      setPurchaseToken(null);
      setPixPayload('');
      setQrCodeUrl('');
      setGenerationError(null);
      return;
    }

    const currentKey = `${activeContext.type}_${activeContext.id}_${retryCount}`;
    if (pixCreatedForRef.current === currentKey) {
      return;
    }
    pixCreatedForRef.current = currentKey;

    let isMounted = true;
    setDisplayAmount(activeContext.numericPrice);

    if (activeContext.initialPayment?.qrCode) {
      const init = activeContext.initialPayment;
      setOrderId(init.orderId);
      if (init.purchaseToken) setPurchaseToken(init.purchaseToken);
      setPixPayload(init.qrCode);
      if (init.qrCodeUrl) setQrCodeUrl(init.qrCodeUrl);
      if (init.amount) setDisplayAmount(init.amount);
      setIsGeneratingPix(false);
      setGenerationError(null);
      return;
    }

    setIsGeneratingPix(true);
    setGenerationError(null);

    const apiUrl = getPublicApiUrl();
    const endpoint = `${apiUrl}/api/payments/create-pix`;

    fetch(endpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        type: activeContext.type,
        slug: activeContext.id,
        productId: activeContext.id,
        price: activeContext.numericPrice,
        title: activeContext.title,
        payerEmail: buyerEmail || undefined,
        simulate: isLocal,
      }),
    })
      .then(async (res) => {
        const data = await res.json().catch(() => ({}));
        if (!res.ok || !data.success) {
          throw new Error(data.error || `Erro de comunicação HTTP ${res.status}`);
        }
        return data;
      })
      .then((data: any) => {
        if (!isMounted) return;

        if (data.success && data.qrCode) {
          setOrderId(data.orderId);
          if (data.purchaseToken) setPurchaseToken(data.purchaseToken);
          setPixPayload(data.qrCode);
          setQrCodeUrl(data.qrCodeUrl || data.qrCodeBase64 || '');
          if (data.amount) setDisplayAmount(data.amount);
        } else {
          throw new Error(data.error || 'Não foi possível gerar a chave Pix oficial.');
        }
      })
      .catch((err) => {
        if (!isMounted) return;
        console.error('[Checkout Pix]', err);
        setGenerationError(
          err?.message || 'Não foi possível gerar o Pix agora. Tente novamente em instantes.'
        );
      })
      .finally(() => {
        if (isMounted) setIsGeneratingPix(false);
      });

    return () => {
      isMounted = false;
    };
  }, [isOpen, activeContext, retryCount, isLocal]);

  // Polling automático no servidor para detectar aprovação do Pix em tempo real
  useEffect(() => {
    if (!isOpen || !orderId || paymentStatus === 'approved' || paymentStatus === 'rejected') return;

    const apiUrl = getPublicApiUrl();
    const endpoint = `${apiUrl}/api/payments/status?orderId=${encodeURIComponent(orderId)}`;

    const pollInterval = setInterval(() => {
      fetch(endpoint)
        .then((r) => r.json())
        .then((data: any) => {
          if (data.success && (data.paid || data.status === 'approved')) {
            setPaymentStatus('approved');
            const tokenToSave = data.order?.purchaseToken || purchaseToken || orderId;
            saveAccessLocally(tokenToSave);
            onSuccess?.({ orderId, purchaseToken: tokenToSave });
            clearInterval(pollInterval);
          } else if (data.status === 'rejected' || data.status === 'cancelled') {
            setPaymentStatus('rejected');
            clearInterval(pollInterval);
          }
        })
        .catch(() => {});
    }, 2800);

    return () => clearInterval(pollInterval);
  }, [isOpen, orderId, paymentStatus, purchaseToken, onSuccess]);

  const retryOrder = (options?: { resetTime?: boolean }) => {
    setPaymentStatus('pending');
    if (options?.resetTime) {
      setTimeLeft(15 * 60);
    }
    setRetryCount((c) => c + 1);
  };

  const formatTimer = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
  };

  return {
    activeContext,
    isLocal,
    copied,
    pixPayload,
    qrCodeUrl,
    timeLeft,
    formatTimer,
    paymentStatus,
    orderId,
    displayAmount,
    isGeneratingPix,
    generationError,
    paymentMethodTab,
    setPaymentMethodTab,
    isRedirectingToCard,
    cardError,
    buyerEmail,
    setBuyerEmail,
    emailError,
    recoveryEmailInput,
    setRecoveryEmailInput,
    isRecoveringEmail,
    recoveryMsg,
    isSimulating,
    handleCopyPix,
    handleSaveBuyerEmail,
    handleQuickRecoverEmail,
    handleSimulateApprove,
    handleStartCardCheckout,
    retryOrder,
  };
}

'use client';

import React, { useEffect, useRef, useState, useCallback } from 'react';
import type { MusicTrack } from '@/lib/music';
import { getTrackVideoInfo } from '@/lib/music/mediaHelpers';
import { useMusicPlayer } from '@/lib/music';
import { Film, Maximize2 } from 'lucide-react';

declare global {
  interface Window {
    YT: any;
    onYouTubeIframeAPIReady: () => void;
    _ytIframeApiLoading?: boolean;
    _ytIframeApiReadyCallbacks?: Array<() => void>;
  }
}

interface MiniVideoPlayerProps {
  track: MusicTrack;
  isCompact: boolean;
}

export function MiniVideoPlayer({ track, isCompact }: MiniVideoPlayerProps) {
  const {
    isPlaying,
    volume,
    isMuted,
    registerVideoController,
    unregisterVideoController,
    onVideoTimeUpdate,
    onVideoPlay,
    onVideoPause,
    onVideoEnded,
  } = useMusicPlayer();

  const videoInfo = getTrackVideoInfo(track);
  const containerRef = useRef<HTMLDivElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const ytPlayerRef = useRef<any>(null);
  const ytPollTimerRef = useRef<any>(null);
  const [isReady, setIsReady] = useState(false);
  const [loadError, setLoadError] = useState(false);
  const containerId = useRef(`yt-player-${Math.random().toString(36).slice(2, 8)}`);

  // 1. Suporte a HTML5 Video direto (.mp4, .webm)
  useEffect(() => {
    if (!videoInfo.directVideoUrl) return;

    const vid = videoRef.current;
    if (!vid) return;

    registerVideoController({
      play: () => {
        vid.play().catch(() => {});
      },
      pause: () => {
        vid.pause();
      },
      seekTo: (time: number) => {
        try {
          vid.currentTime = time;
        } catch {}
      },
      setVolume: (v: number) => {
        vid.volume = Math.max(0, Math.min(1, v));
      },
      setMuted: (m: boolean) => {
        vid.muted = m;
      },
    });

    vid.volume = volume;
    vid.muted = isMuted;

    if (isPlaying) {
      vid.play().catch(() => {});
    } else {
      vid.pause();
    }

    return () => {
      unregisterVideoController();
    };
  }, [videoInfo.directVideoUrl, registerVideoController, unregisterVideoController]);

  // 2. Carregar YouTube IFrame API de forma segura e assíncrona
  const ensureYouTubeAPI = useCallback((onReadyCb: () => void) => {
    if (typeof window === 'undefined') return;

    if (window.YT && window.YT.Player) {
      onReadyCb();
      return;
    }

    if (!window._ytIframeApiReadyCallbacks) {
      window._ytIframeApiReadyCallbacks = [];
    }
    window._ytIframeApiReadyCallbacks.push(onReadyCb);

    if (window._ytIframeApiLoading) return;
    window._ytIframeApiLoading = true;

    const existingScript = document.getElementById('youtube-iframe-api');
    if (!existingScript) {
      const tag = document.createElement('script');
      tag.id = 'youtube-iframe-api';
      tag.src = 'https://www.youtube.com/iframe_api';
      tag.async = true;
      document.head.appendChild(tag);
    }

    const prevOnReady = window.onYouTubeIframeAPIReady;
    window.onYouTubeIframeAPIReady = () => {
      if (typeof prevOnReady === 'function') {
        try {
          prevOnReady();
        } catch {}
      }
      if (window._ytIframeApiReadyCallbacks) {
        window._ytIframeApiReadyCallbacks.forEach((cb) => {
          try {
            cb();
          } catch {}
        });
        window._ytIframeApiReadyCallbacks = [];
      }
    };
  }, []);

  // 3. Montar / inicializar player do YouTube
  useEffect(() => {
    if (!videoInfo.isYouTube || !videoInfo.youtubeId) return;

    let destroyed = false;
    setIsReady(false);
    setLoadError(false);

    ensureYouTubeAPI(() => {
      if (destroyed || !containerRef.current) return;

      try {
        if (ytPlayerRef.current) {
          try {
            ytPlayerRef.current.destroy();
          } catch {}
          ytPlayerRef.current = null;
        }

        const ytId = videoInfo.youtubeId!;
        const playerElement = document.createElement('div');
        playerElement.id = containerId.current;
        containerRef.current.innerHTML = '';
        containerRef.current.appendChild(playerElement);

        ytPlayerRef.current = new window.YT.Player(containerId.current, {
          videoId: ytId,
          playerVars: {
            autoplay: isPlaying ? 1 : 0,
            controls: 1,
            modestbranding: 1,
            rel: 0,
            playsinline: 1,
            enablejsapi: 1,
            iv_load_policy: 3,
            origin: typeof window !== 'undefined' ? window.location.origin : undefined,
          },
          events: {
            onReady: (event: any) => {
              if (destroyed) return;
              setIsReady(true);
              try {
                if (isMuted) {
                  event.target.mute();
                } else {
                  event.target.unMute();
                  event.target.setVolume(Math.round(volume * 100));
                }
                if (isPlaying) {
                  event.target.playVideo();
                }
              } catch {}
            },
            onStateChange: (event: any) => {
              if (destroyed) return;
              // 1 = PLAYING, 2 = PAUSED, 0 = ENDED, 3 = BUFFERING
              if (event.data === 1) {
                onVideoPlay();
              } else if (event.data === 2) {
                onVideoPause();
              } else if (event.data === 0) {
                onVideoEnded();
              }
            },
            onError: () => {
              if (destroyed) return;
              setLoadError(true);
            },
          },
        });

        registerVideoController({
          play: () => {
            try {
              ytPlayerRef.current?.playVideo();
            } catch {}
          },
          pause: () => {
            try {
              ytPlayerRef.current?.pauseVideo();
            } catch {}
          },
          seekTo: (time: number) => {
            try {
              ytPlayerRef.current?.seekTo(time, true);
            } catch {}
          },
          setVolume: (v: number) => {
            try {
              ytPlayerRef.current?.setVolume(Math.round(v * 100));
            } catch {}
          },
          setMuted: (m: boolean) => {
            try {
              if (m) ytPlayerRef.current?.mute();
              else ytPlayerRef.current?.unMute();
            } catch {}
          },
        });
      } catch (err) {
        console.warn('[MiniVideoPlayer] Falha ao criar player do YouTube:', err);
        setLoadError(true);
      }
    });

    return () => {
      destroyed = true;
      unregisterVideoController();
      if (ytPollTimerRef.current) {
        clearInterval(ytPollTimerRef.current);
        ytPollTimerRef.current = null;
      }
      if (ytPlayerRef.current) {
        try {
          ytPlayerRef.current.destroy();
        } catch {}
        ytPlayerRef.current = null;
      }
    };
  }, [
    videoInfo.isYouTube,
    videoInfo.youtubeId,
    ensureYouTubeAPI,
    registerVideoController,
    unregisterVideoController,
    onVideoPlay,
    onVideoPause,
    onVideoEnded,
  ]);

  // 4. Polling contínuo de tempo e duração do YouTube
  useEffect(() => {
    if (!videoInfo.isYouTube) return;

    if (isPlaying) {
      if (ytPollTimerRef.current) clearInterval(ytPollTimerRef.current);
      ytPollTimerRef.current = setInterval(() => {
        if (ytPlayerRef.current && typeof ytPlayerRef.current.getCurrentTime === 'function') {
          try {
            const cur = ytPlayerRef.current.getCurrentTime() || 0;
            const dur = ytPlayerRef.current.getDuration() || 0;
            onVideoTimeUpdate(cur, dur);
          } catch {}
        }
      }, 350);
    } else {
      if (ytPollTimerRef.current) {
        clearInterval(ytPollTimerRef.current);
        ytPollTimerRef.current = null;
      }
    }

    return () => {
      if (ytPollTimerRef.current) {
        clearInterval(ytPollTimerRef.current);
        ytPollTimerRef.current = null;
      }
    };
  }, [isPlaying, videoInfo.isYouTube, onVideoTimeUpdate]);

  // 5. Sincronizar volume e mute dinamicamente no YouTube
  useEffect(() => {
    if (!videoInfo.isYouTube || !ytPlayerRef.current) return;
    try {
      if (isMuted) {
        ytPlayerRef.current.mute?.();
      } else {
        ytPlayerRef.current.unMute?.();
        ytPlayerRef.current.setVolume?.(Math.round(volume * 100));
      }
    } catch {}
  }, [volume, isMuted, videoInfo.isYouTube]);

  // Se a faixa atual não for vídeo, não renderiza nada
  if (!videoInfo.isVideo) {
    return null;
  }

  const handleRequestFullscreen = () => {
    const el = containerRef.current || videoRef.current;
    if (el) {
      if (el.requestFullscreen) {
        el.requestFullscreen();
      } else if ((el as any).webkitRequestFullscreen) {
        (el as any).webkitRequestFullscreen();
      }
    }
  };

  return (
    <div
      aria-hidden={isCompact}
      className={
        isCompact
          ? 'fixed -top-[9999px] -left-[9999px] w-[1px] h-[1px] opacity-0 pointer-events-none overflow-hidden'
          : 'relative w-full aspect-video rounded-xl overflow-hidden bg-black/95 border border-white/10 shadow-[0_8px_30px_rgba(0,0,0,0.7)] group transition-all duration-300'
      }
    >
      {/* Container para YouTube */}
      {videoInfo.isYouTube && (
        <div
          ref={containerRef}
          className="w-full h-full object-cover [&_iframe]:w-full [&_iframe]:h-full [&_iframe]:border-0 [&_iframe]:rounded-xl"
        />
      )}

      {/* Container para Vídeo Direto (HTML5) */}
      {videoInfo.directVideoUrl && (
        <video
          ref={videoRef}
          src={videoInfo.directVideoUrl}
          playsInline
          preload="auto"
          className="w-full h-full object-cover rounded-xl"
          onPlay={onVideoPlay}
          onPause={onVideoPause}
          onEnded={onVideoEnded}
          onTimeUpdate={() => {
            if (videoRef.current) {
              onVideoTimeUpdate(videoRef.current.currentTime, videoRef.current.duration || 0);
            }
          }}
        />
      )}

      {/* Badge Editorial Superior Esquerdo */}
      <div className="absolute top-2 left-2 z-10 flex items-center gap-1.5 px-2 py-0.5 rounded-full bg-black/70 backdrop-blur-md border border-white/10 pointer-events-none transition-opacity duration-200">
        <span className="w-1.5 h-1.5 rounded-full bg-[#f4a7b9] animate-pulse" />
        <Film className="w-2.5 h-2.5 text-[#f4a7b9]" />
        <span className="text-[9px] font-mono tracking-widest uppercase text-white/90 font-medium">
          {videoInfo.providerBadge}
        </span>
      </div>

      {/* Botão de Tela Cheia / PiP no canto superior direito */}
      <button
        type="button"
        onClick={handleRequestFullscreen}
        aria-label="Expandir vídeo em tela cheia"
        className="absolute top-2 right-2 z-10 w-6 h-6 rounded-full bg-black/60 hover:bg-black/90 text-white/70 hover:text-white border border-white/10 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-all cursor-pointer"
        title="Tela cheia"
      >
        <Maximize2 className="w-3 h-3" />
      </button>

      {/* Mensagem de Erro Caso o Vídeo Falhe */}
      {loadError && (
        <div className="absolute inset-0 bg-black/85 flex flex-col items-center justify-center p-3 text-center z-20">
          <p className="text-[11px] text-zinc-300 font-medium">Vídeo indisponível externamente</p>
          <p className="text-[9px] text-zinc-500 mt-0.5">A reprodução de áudio continuará na playlist</p>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useRef, useCallback } from 'react';
import type { RefObject } from 'react';
import type { MusicTrack, MusicLibrary } from './types';
import { DEFAULT_LIBRARY } from './types';
import {
  loadSavedVolume,
  saveVolume,
  loadSavedPosition,
  savePosition,
  loadDurationCache,
} from './persistence';
import {
  updateMediaSessionMetadata,
  updateMediaSessionPlayback,
  setupMediaSessionHandlers,
} from './mediaSession';
import { calculateFrequencyBars } from './equalizer';
import { useMusicShortcuts } from './useMusicShortcuts';
import { useMusicFades } from './useMusicFades';
import { useMusicAudioEvents } from './useMusicAudioEvents';
import { subscribeAdminUpdates } from '@/lib/adminSync';
import { useCrossTabAudioSync } from './useCrossTabAudioSync';
import { getTrackVideoInfo } from './mediaHelpers';
import type { VideoController } from './store';

import { getPublicApiUrl } from '../contentStore';

/**
 * Motor do player de música.
 *
 * `providedAudioRef` permite ao componente que renderiza o `<audio>` injetar o próprio
 * ref (o `MusicProvider`), em vez de ler um ref devolvido pelo hook durante o render.
 * Quando não informado, o hook cria o ref internamente (comportamento anterior).
 */
export function useMusicPlayerEngine(
  isAdmin: boolean,
  providedAudioRef?: RefObject<HTMLAudioElement | null>
) {
  const [library, setLibrary] = useState<MusicLibrary>(DEFAULT_LIBRARY);
  const [isLibraryLoaded, setIsLibraryLoaded] = useState(false);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [volume, setVolumeState] = useState(0.7);
  const [isMuted, setIsMuted] = useState(false);
  const [isPlaylistOpen, setIsPlaylistOpen] = useState(false);
  const [repeatMode, setRepeatMode] = useState<'none' | 'one' | 'all'>('none');
  const [shuffleMode, setShuffleMode] = useState(false);
  const [autoplayBlocked, setAutoplayBlocked] = useState(false);

  const localAudioRef = useRef<HTMLAudioElement | null>(null);
  const audioRef = providedAudioRef ?? localAudioRef;
  const prefetchAudioRef = useRef<HTMLAudioElement | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const freqDataRef = useRef<Uint8Array | null>(null);

  const positionSaveRef = useRef<any>(null);
  const pendingSeekRef = useRef<{ trackId: string; time: number } | null>(null);
  const retryCountRef = useRef(0);
  const retryTimerRef = useRef<any>(null);

  const playHistoryRef = useRef<number[]>([]);

  const activeTracks = library.tracks.filter((t) => t.active);
  const currentTrack: MusicTrack | undefined = activeTracks[currentIndex];

  const videoControllerRef = useRef<VideoController | null>(null);

  const registerVideoController = useCallback((controller: VideoController) => {
    videoControllerRef.current = controller;
  }, []);

  const unregisterVideoController = useCallback(() => {
    videoControllerRef.current = null;
  }, []);

  const onVideoTimeUpdate = useCallback((cur: number, dur: number) => {
    setCurrentTime(cur);
    if (dur > 0 && isFinite(dur)) {
      setDuration(Math.round(dur));
    }
  }, []);

  const onVideoPlay = useCallback(() => {
    setIsPlaying(true);
    setAutoplayBlocked(false);
    setIsLoading(false);
    setError(null);
  }, []);

  const onVideoPause = useCallback(() => {
    setIsPlaying(false);
  }, []);

  const { applyVolume, fadeIn, fadeOut, isFadingRef, cleanupFades } = useMusicFades({
    audioRef,
    volume,
    isMuted,
  });

  const {
    initWebAudio,
    suspendAudioContext,
    resumeAudioContext,
    broadcastPlay,
    closeAudioContext,
  } = useCrossTabAudioSync({
    audioRef,
    isPlaying,
    setIsPlaying,
  });

  const reloadLibrary = useCallback(async () => {
    try {
      const apiUrl = getPublicApiUrl();
      const res = await fetch(`${apiUrl}/api/music/list`, { cache: 'no-store' });
      if (!res.ok) return;
      const data: MusicLibrary = await res.json();
      if (data && Array.isArray(data.tracks)) {
        const durationCache = loadDurationCache();
        const hydratedTracks = data.tracks.map((t) => ({
          ...t,
          duration: t.duration || durationCache[t.id] || null,
        }));
        setLibrary({ ...data, tracks: hydratedTracks });
      }
    } catch (e) {
      console.warn('[MusicStore] Falha ao carregar biblioteca:', e);
    } finally {
      setIsLibraryLoaded(true);
    }
  }, []);

  useEffect(() => {
    if (typeof window === 'undefined') return;
    reloadLibrary();
  }, [reloadLibrary]);

  // Alteração de faixas/config no painel (ou pela IA) atualiza o player na hora.
  useEffect(() => subscribeAdminUpdates('music', () => reloadLibrary()), [reloadLibrary]);

  useEffect(() => {
    if (typeof window === 'undefined') return;
    const saved = loadSavedVolume();
    setVolumeState(saved);

    const savedPos = loadSavedPosition();
    if (savedPos) {
      pendingSeekRef.current = savedPos;
    }
  }, []);

  const prefetchNextTrack = useCallback((nextIdx: number) => {
    const nextT = activeTracks[nextIdx];
    if (!nextT?.url || typeof window === 'undefined') return;

    try {
      if (!prefetchAudioRef.current) {
        prefetchAudioRef.current = new Audio();
        prefetchAudioRef.current.preload = 'metadata';
      }
      if (prefetchAudioRef.current.src !== nextT.url) {
        prefetchAudioRef.current.src = nextT.url;
        prefetchAudioRef.current.load();
      }
    } catch { }
  }, [activeTracks]);

  const loadTrack = useCallback((track: MusicTrack, autoResume: boolean) => {
    const audio = audioRef.current;
    if (!audio) return;

    if (retryTimerRef.current) clearTimeout(retryTimerRef.current);
    retryCountRef.current = 0;

    const videoInfo = getTrackVideoInfo(track);
    if (videoInfo.isVideo) {
      audio.pause();
      try {
        audio.removeAttribute('src');
        audio.load();
      } catch { }

      setDuration(track.duration || 0);
      setCurrentTime(0);
      setError(null);
      setIsLoading(false);

      if (autoResume) {
        setIsPlaying(true);
        setAutoplayBlocked(false);
        if (videoControllerRef.current) {
          videoControllerRef.current.play();
        }
      }
      return;
    }

    if (!track.url) return;

    audio.pause();
    if (!audio.src || !audio.src.includes(track.url)) {
      audio.src = track.url;
      audio.preload = 'auto';
      audio.load();
    }

    setDuration(track.duration || 0);
    setCurrentTime(0);
    setError(null);
    setIsLoading(true);

    if (autoResume) {
      applyVolume(1);
      audio.muted = false;
      audio.play()
        .then(() => {
          setIsPlaying(true);
          setAutoplayBlocked(false);
          setIsLoading(false);
          resumeAudioContext();
          broadcastPlay();

          const pending = pendingSeekRef.current;
          if (pending && pending.trackId === track.id) {
            pendingSeekRef.current = null;
            try { audio.currentTime = pending.time; } catch { }
          }
        })
        .catch(() => {
          setAutoplayBlocked(true);
          setIsLoading(false);
          audio.muted = true;
          audio.play().then(() => setIsPlaying(true)).catch(() => setIsPlaying(false));
        });
    }
  }, [applyVolume, resumeAudioContext, broadcastPlay, audioRef]);

  useEffect(() => {
    if (!currentTrack || !audioRef.current) return;
    const videoInfo = getTrackVideoInfo(currentTrack);
    if (videoInfo.isVideo) return;
    if (!currentTrack.url) return;
    const audio = audioRef.current;
    if (!audio.src || !audio.src.includes(currentTrack.url)) {
      audio.src = currentTrack.url;
      audio.preload = 'none';
    }
  }, [currentTrack, audioRef]);

  useEffect(() => {
    if (!currentTrack) return;
    loadTrack(currentTrack, isPlaying);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentIndex]);

  const handleNetworkRecovery = useCallback(() => {
    const audio = audioRef.current;
    if (!audio || !currentTrack) return;

    if (retryCountRef.current < 3) {
      const delay = Math.min(3000, 500 * Math.pow(2, retryCountRef.current));
      retryCountRef.current++;

      if (retryTimerRef.current) clearTimeout(retryTimerRef.current);
      retryTimerRef.current = setTimeout(() => {
        const savedTime = audio.currentTime;
        audio.load();
        audio.currentTime = savedTime;
        audio.play().then(() => {
          setIsPlaying(true);
          setError(null);
          retryCountRef.current = 0;
        }).catch(() => { });
      }, delay);
    } else {
      setIsLoading(false);
      setIsPlaying(false);
      setError('Conexão instável. Verifique sua rede e tente novamente.');
    }
  }, [currentTrack, audioRef]);

  useMusicAudioEvents({
    audioRef,
    currentTrack,
    currentIndex,
    activeTracksCount: activeTracks.length,
    isPlaying,
    repeatMode,
    shuffleMode,
    isFadingRef,
    playHistoryRef,
    fadeOut,
    prefetchNextTrack,
    handleNetworkRecovery,
    resumeAudioContext,
    suspendAudioContext,
    setCurrentTime,
    setDuration,
    setIsPlaying,
    setAutoplayBlocked,
    setIsLoading,
    setError,
    setCurrentIndex,
  });

  useEffect(() => {
    if (!isPlaying || !currentTrack) return;
    if (positionSaveRef.current) clearInterval(positionSaveRef.current);
    positionSaveRef.current = setInterval(() => {
      if (currentTrack && audioRef.current) {
        savePosition(currentTrack.id, Math.floor(audioRef.current.currentTime));
      }
    }, 5000);
    return () => {
      if (positionSaveRef.current) clearInterval(positionSaveRef.current);
    };
  }, [isPlaying, currentTrack, audioRef]);

  useEffect(() => {
    updateMediaSessionMetadata(currentTrack, library.config.playlistTitle);
  }, [currentTrack, library.config.playlistTitle]);

  useEffect(() => {
    updateMediaSessionPlayback(isPlaying, duration, currentTime);
  }, [isPlaying, duration, currentTime]);

  useEffect(() => {
    return () => {
      cleanupFades();
      closeAudioContext();
      if (positionSaveRef.current) clearInterval(positionSaveRef.current);
      if (retryTimerRef.current) clearTimeout(retryTimerRef.current);
    };
  }, [cleanupFades, closeAudioContext]);

  const play = useCallback(() => {
    const videoInfo = getTrackVideoInfo(currentTrack);
    if (videoInfo.isVideo) {
      setIsPlaying(true);
      setAutoplayBlocked(false);
      setError(null);
      setIsLoading(false);
      broadcastPlay();
      if (videoControllerRef.current) {
        videoControllerRef.current.play();
      }
      return;
    }

    const audio = audioRef.current;
    if (!audio) return;

    initWebAudio();
    resumeAudioContext();

    if (currentTrack?.url && (!audio.src || !audio.src.includes(currentTrack.url))) {
      audio.src = currentTrack.url;
      audio.preload = 'auto';
    }

    applyVolume(1);
    audio.muted = false;
    audio.play()
      .then(() => {
        setIsPlaying(true);
        setAutoplayBlocked(false);
        setError(null);
        setIsLoading(false);
        broadcastPlay();
      })
      .catch((err) => {
        console.warn('[MusicStore] Erro ao reproduzir áudio:', err);
        setAutoplayBlocked(true);
        setIsLoading(false);
        setIsPlaying(false);
      });
  }, [currentTrack, initWebAudio, resumeAudioContext, applyVolume, broadcastPlay, audioRef]);

  const pause = useCallback(() => {
    const videoInfo = getTrackVideoInfo(currentTrack);
    if (videoInfo.isVideo) {
      setIsPlaying(false);
      if (videoControllerRef.current) {
        videoControllerRef.current.pause();
      }
      return;
    }

    fadeOut(200).then(() => {
      audioRef.current?.pause();
      setIsPlaying(false);
      applyVolume(1);
      suspendAudioContext();
    });
  }, [currentTrack, fadeOut, applyVolume, suspendAudioContext, audioRef]);

  const toggle = useCallback(() => {
    if (isPlaying) pause();
    else play();
  }, [isPlaying, play, pause]);

  const next = useCallback(() => {
    if (activeTracks.length === 0) return;
    const videoInfo = getTrackVideoInfo(currentTrack);
    const advance = () => {
      if (shuffleMode && activeTracks.length > 1) {
        playHistoryRef.current.push(currentIndex);
        let nextIdx = currentIndex;
        while (nextIdx === currentIndex) {
          nextIdx = Math.floor(Math.random() * activeTracks.length);
        }
        setCurrentIndex(nextIdx);
      } else {
        setCurrentIndex((i) => (i + 1) % activeTracks.length);
      }
      setIsPlaying(true);
    };

    if (videoInfo.isVideo) {
      advance();
    } else {
      fadeOut(150).then(advance);
    }
  }, [activeTracks.length, currentIndex, currentTrack, shuffleMode, fadeOut]);

  const onVideoEnded = useCallback(() => {
    next();
  }, [next]);

  const prev = useCallback(() => {
    if (activeTracks.length === 0) return;
    const videoInfo = getTrackVideoInfo(currentTrack);
    if (videoInfo.isVideo) {
      if (currentTime > 3) {
        seekTo(0);
        return;
      }
    } else {
      const audio = audioRef.current;
      if (audio && audio.currentTime > 3) {
        audio.currentTime = 0;
        return;
      }
    }

    const rewind = () => {
      if (shuffleMode && playHistoryRef.current.length > 0) {
        const lastIdx = playHistoryRef.current.pop();
        if (typeof lastIdx === 'number') {
          setCurrentIndex(lastIdx);
          setIsPlaying(true);
          return;
        }
      }
      setCurrentIndex((i) => (i - 1 + activeTracks.length) % activeTracks.length);
      setIsPlaying(true);
    };

    if (videoInfo.isVideo) {
      rewind();
    } else {
      fadeOut(150).then(rewind);
    }
  }, [activeTracks.length, currentTrack, currentTime, shuffleMode, fadeOut, audioRef]);

  const seekTo = useCallback((time: number) => {
    const clamped = Math.max(0, Math.min(time, duration || time));
    setCurrentTime(clamped);

    const videoInfo = getTrackVideoInfo(currentTrack);
    if (videoInfo.isVideo) {
      if (videoControllerRef.current) {
        videoControllerRef.current.seekTo(clamped);
      }
      return;
    }

    const audio = audioRef.current;
    if (!audio) return;
    try {
      if (typeof (audio as any).fastSeek === 'function') {
        (audio as any).fastSeek(clamped);
      } else {
        audio.currentTime = clamped;
      }
    } catch { }
  }, [duration, currentTrack, audioRef]);

  const setVolume = useCallback((v: number) => {
    const clamped = Math.max(0, Math.min(1, v));
    setVolumeState(clamped);
    setIsMuted(false);
    saveVolume(clamped);
    if (videoControllerRef.current) {
      videoControllerRef.current.setVolume(clamped);
      videoControllerRef.current.setMuted(false);
    }
  }, []);

  const toggleMute = useCallback(() => {
    setIsMuted((prev) => {
      const nextMuted = !prev;
      if (videoControllerRef.current) {
        videoControllerRef.current.setMuted(nextMuted);
      }
      return nextMuted;
    });
  }, []);

  const setTrack = useCallback((index: number) => {
    if (index >= 0 && index < activeTracks.length) {
      if (shuffleMode) {
        playHistoryRef.current.push(currentIndex);
      }
      fadeOut(150).then(() => {
        setCurrentIndex(index);
        setIsPlaying(true);
      });
    }
  }, [activeTracks.length, currentIndex, shuffleMode, fadeOut]);

  const toggleRepeat = useCallback(() => {
    setRepeatMode((prev) => {
      if (prev === 'none') return 'all';
      if (prev === 'all') return 'one';
      return 'none';
    });
  }, []);

  const toggleShuffle = useCallback(() => {
    setShuffleMode((prev) => !prev);
  }, []);

  useMusicShortcuts({
    toggle,
    toggleMute,
    next,
    prev,
    seekTo,
    currentTime,
    duration,
  });

  const getFrequencyBars = useCallback((): [number, number, number] => {
    if (!freqDataRef.current && analyserRef.current) {
      freqDataRef.current = new Uint8Array(analyserRef.current.frequencyBinCount);
    }
    return calculateFrequencyBars(
      analyserRef.current,
      freqDataRef.current,
      isPlaying,
      isMuted,
      volume
    );
  }, [isPlaying, isMuted, volume]);

  useEffect(() => {
    return setupMediaSessionHandlers({
      play,
      pause,
      prev,
      next,
      seekTo,
      getCurrentTime: () => audioRef.current?.currentTime || 0,
      getDuration: () => duration || audioRef.current?.duration || 0,
    });
  }, [play, pause, prev, next, seekTo, duration, audioRef]);

  useEffect(() => {
    if (!isLibraryLoaded || isAdmin || !library.config?.autoplay || !currentTrack) return;
    const timer = setTimeout(() => {
      play();
    }, 600);
    return () => clearTimeout(timer);
  }, [isLibraryLoaded, isAdmin, library.config?.autoplay, currentTrack, play]);

  return {
    library,
    currentIndex,
    currentTrack,
    isPlaying,
    currentTime,
    duration,
    isLoading,
    error,
    volume,
    isMuted,
    isPlaylistOpen,
    repeatMode,
    shuffleMode,
    autoplayBlocked,
    isLibraryLoaded,
    play,
    pause,
    toggle,
    next,
    prev,
    seekTo,
    setVolume,
    toggleMute,
    setTrack,
    setIsPlaylistOpen,
    toggleRepeat,
    toggleShuffle,
    audioRef,
    analyserRef,
    getFrequencyBars,
    reloadLibrary,
    registerVideoController,
    unregisterVideoController,
    onVideoTimeUpdate,
    onVideoPlay,
    onVideoPause,
    onVideoEnded,
  };
}
